// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.screenimport timber.log.Timberimport android.graphics.Bitmapimport android.graphics.Canvasimport android.view.Viewimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Android Screenshot Capturer (Module 6 v4 — Step 6.6). * * Captures a screenshot by drawing a target [View]'s contents into a * [Bitmap], then encoding it as JPEG bytes for downstream OCR / UI-element * detection. * * ## Why a View-based capturer * * The full [AccessibilityService.takeScreenshot] API requires API 30+ and * a live accessibility service. This capturer works on any [View] the caller * supplies (e.g., a Compose `AndroidView`, a `SurfaceView` preview, or any * window's root view) — useful for tests, on-screen overlays, and the * "describe what I'm pointing at" UX where the caller already has the view. * * ## Privacy * *  - The captured [Bitmap] is encoded to JPEG in RAM, then immediately *    recycled. The byte array is handed to OCR / detection, which processes *    and discards it. *  - Nothing is persisted to disk. * * @see ScreenshotCapturer */@Singletonclass AndroidScreenshotCapturer @Inject constructor() : ScreenshotCapturer {    @Volatile    private var attachedView: View? = null    /**     * Attach the [View] that subsequent [capture] calls will snapshot.     *     * Call this from `Activity.onResume()` (or equivalent) with the window's     * root view. Detach in `onPause()` via [detachView].     */    fun attachView(view: View) {        attachedView = view        Timber.tag(TAG).d("View attached: ${view.javaClass.simpleName}.")    }    /** Detach the view (call from `Activity.onPause()`). */    fun detachView() {        attachedView = null    }    override suspend fun capture(): ByteArray? {        val view = attachedView ?: run {            Timber.tag(TAG).w("No View attached — capture() returning null.")            return null        }        if (view.width <= 0 || view.height <= 0) {            Timber.tag(TAG).w("Attached view has zero dimensions (${view.width}x${view.height}).")            return null        }        val bitmap = Bitmap.createBitmap(view.width, view.height, Bitmap.Config.ARGB_8888)        return try {            val canvas = Canvas(bitmap)            view.draw(canvas)            val stream = java.io.ByteArrayOutputStream()            bitmap.compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, stream)            val bytes = stream.toByteArray()            Timber.tag(TAG).d("Captured screenshot: ${view.width}x${view.height}, ${bytes.size} bytes.")            bytes        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to capture screenshot.", t)            null        } finally {            bitmap.recycle()        }    }    override fun isAvailable(): Boolean = attachedView != null    private companion object {        private const val TAG = "AndroidScreenshot"        private const val JPEG_QUALITY = 85    }}